/**
 * The inputs of one tap (contracts.md §3) — what `@app/data` `loadRegsInputs()` reads from the release files (water,
 * regs-<region>, regs-sid; README §0) and core hydrates. Types only: T04/T06/T07/T09 fill the bodies that build them
 * (T06: `RuleView`/`RuleIndex` are built by rules.ts).
 *
 * The store-wire types come from `../answers.generated` (generated by Python); only the ones the regs modules name are
 * re-exported, and its `Place` as `AnswersPlace` (core's index must not take the generated file wholesale).
 */
import type {
  GearValue, GlossaryTerm, LicenceValue, Moment, PartFacts, Picker, RowsValue, RuleFacts, StatusFrame, StripState,
  TidalStatus,
} from "../answers.generated";
import type { Day, RegsTarget, Weekday } from "./model";
import type { RuleKey } from "./line";
import type { SpeciesBook } from "./names";
import type { Md } from "./time";

export type {
  RowsValue, Row, Decided, FishAnswer, GearAnswer, GearValue, StatusFrame, LicenceValue, ProfileAnswer, Holds, TidalHolds,
  UnderSixteen, RuleFacts, PartFacts, Picker, Choice, Moment, MomentHours, ClockTime, GlossaryTerm, StripState, InheritedLift,
  Place as AnswersPlace,
} from "../answers.generated";

/** A tidal key's frame is {status:"tidal", tidal, note, see, licence}. */
export type DisplayFrame = StatusFrame | TidalStatus;
export interface CellIds { readonly ladder: number; readonly rows: number; readonly gear: number; readonly licence: number; readonly display: number }
export type VerdictWire = readonly [speaks: readonly number[], beside: readonly number[], shown: readonly number[],
  nym: readonly number[], partly: readonly (readonly [number, readonly number[]])[], lost: readonly (readonly [number, number, number])[]];
export interface LadderFrameWire { readonly common: VerdictWire; readonly rows: readonly (readonly [fish: string, none: VerdictWire, hatchery: VerdictWire, wild: VerdictWire])[] }
/** page mergedHtml: only when the part's picker group is closed and has ≥ 2 parts (T09/T14). */
/** (T36 parts sheet) one picker choice's stored display status on the inputs' day, read through the choice's first part's
 *  key — the same frame that part's own page reads for its header and strip (`settled.status`); null: the part has no key. */
export interface ChoiceDay { readonly partIx: number; readonly status: DisplayFrame["status"] | null }
export interface MergedPart { readonly partIx: number; readonly label: string; readonly sections: number; readonly broad: RuleView | null }

export interface RegsYear {
  readonly segStarts: readonly number[];
  readonly moments: readonly Moment[] | null;
  readonly cells: readonly CellIds[];                     // index = s, length = key.nseg
  readonly ladderBySeg: readonly (LadderFrameWire | null)[];
  readonly rowsBySeg: readonly (RowsValue | null)[];      // the joined wire value; rowsAt hydrates it
  readonly displayBySeg: readonly (DisplayFrame | null)[];
  readonly displayByDay: readonly (DisplayFrame | null)[]; // 366, leap calendar, index d-1; the SAME object for equal frame ids
}

export interface RegsInputs {
  readonly target: RegsTarget; readonly day: Day; readonly weekday: Weekday;
  readonly calendarYear: number;                            // the selected date's year: names every day's weekday (page YEAR)
  readonly item: { readonly id: string; readonly ord: number; readonly name: string; readonly kind: string; readonly sections: number;
                   readonly parts: readonly (PartFacts | null)[]; readonly partSections: readonly number[];
                   readonly picker: Picker | null; readonly steelhead: 1 | 2 | null;
                   /** (T15b) the store's `item.unresolved` rules as rix — page v36 WATERS[].uncertain; T09 does not load it yet (absent = none). */
                   readonly uncertain?: readonly number[] } | null;
  readonly partIx: number;
  readonly place: { readonly label: string; readonly name: string } | null;   // an unnamed section: place label + names[kind]
  readonly key: AkeyRow | null;                             // null = outside B.C. (or an item with no rule set on this part)
  readonly s: number | null; readonly cell: CellIds | null;
  readonly frames: { readonly ladder: LadderFrameWire; readonly rows: RowsValue; readonly gear: GearValue;
                     readonly licence: LicenceValue; readonly display: DisplayFrame } | null;
  readonly year: RegsYear | null;
  readonly ruleset: { readonly reach: readonly number[]; readonly trib: readonly number[] } | null;
  readonly rules: RuleIndex;                                // every store rule, viewed through THIS part's via/rank; get() never misses
  readonly lics: ReadonlyMap<number, unknown>;              // export licensing words by lix
  readonly statics: Statics;
  readonly mergedParts: readonly MergedPart[] | null;
  /** (T36) the Parts sheet's rows: one per picker choice, in the picker's order — only for a water whose picker offers ≥ 2
   *  choices (else null); absent = not loaded (a hand-built input), and the Parts sheet is then not built. */
  readonly choicesOnDay?: readonly ChoiceDay[] | null;
}

export interface AkeyRow { akey: number; ruleset: number; licensingSet: number | null; steelheadWater: boolean; steelhead: 1 | 2 | null; steelheadRules: boolean; kind: string; tidal: boolean; seg: number; mom: number | null; nseg: number }

/** One store rule as this part sees it (page v36's decoded rule + makePlace.R's per-part via/rank). PER PART: never
 *  share a view across parts. Built by rules.ts `ruleView` / `noRule`. */
export interface RuleView {
  readonly rix: number; readonly key: RuleKey;             // `${entry_id}::${rule_id}`; "#<rix>" for the noRule stand-in
  readonly export: ExportRule; readonly facts: RuleFacts | null;
  readonly f: Readonly<Record<string, unknown>>;           // = export.fields (page r.f)
  readonly kind: RuleFacts["kind"] | null;                 // page r.k
  readonly baseRank: number;                               // export.prov.rank
  readonly via: "reach" | "trib";                          // the part's ruleset list holding it (absent: "reach")
  readonly rank: number;                                   // via trib && baseRank >= 0 → 1, else baseRank (page makePlace.R)
  readonly species: readonly string[]; readonly speciesExcept: readonly string[];   // expanded
  readonly wins: readonly (readonly [Md, Md])[]; readonly tcond: string;
  readonly part: string | null;                            // fields.undrawn_part
  readonly notes: readonly string[];                       // WORDS.UNCERTAIN + why | NO_REASON ; WORDS.CURATOR + review_reason
  readonly missing: boolean;                               // the noRule stand-in
}
export interface RuleIndex { get(rix: number): RuleView; has(rix: number): boolean; readonly size: number;
  /** (T36) the stored rule whose key is `${entry_id}::${rule_id}`, viewed through this part; null: no such rule (a sheet key
   *  naming a rule the store lacks opens nothing). Optional so hand-built test indexes need not carry it. */
  byKey?(key: RuleKey): RuleView | null }

export interface ExportRule { entry_id: string; rule_id: string; type: string; family: string; label: string; verbatim: string; fields: Record<string, unknown>; parts?: Record<string, string>; prov: { rank: number; entry_name?: string; region?: string | null; who?: string; uncertain?: boolean; why?: string | null }; dimension?: string; binds?: string }

export interface Statics {
  glossary: { version: number; terms: readonly GlossaryTerm[] };
  strip: readonly StripState[]; reasons: unknown; fish: unknown; moments: readonly Moment[];
  countNouns: Record<string, readonly string[]>; gearMoments: unknown; conductMeans: Record<string, string>;
  profiles: readonly string[]; profileDims: readonly (readonly [string, readonly string[]])[]; profileLabels: readonly string[]; residencyLabels: unknown;
  exportSpecies: SpeciesBook; exportLicences: unknown; exportConduct: Record<string, string>;
  ladderReasons: unknown; ladderReasonState: unknown;
  pdfPages: Readonly<Record<number, number>>;   // printed → pdf, for glossary pages; source pipeline.common.synopsis_pages — never compute
}
